def _parse_alias(
    self, this: t.Optional[exp.Expression], explicit: bool = False
) -> t.Optional[exp.Expression]:
    # EXCLUDE can be a trailing modifier for the whole projection list. Don't
    # consume it as an implicit alias when it is followed by an exclusion list.
    if (
        not explicit
        and getattr(self, "_redshift_projection_depth", 0)
        and self._curr
        and self._curr.text.upper() == "EXCLUDE"
        and self._next
        and (
            self._next.token_type == TokenType.L_PAREN
            or self._next.token_type in (TokenType.VAR, TokenType.IDENTIFIER)
        )
    ):
        return this

    return super()._parse_alias(this, explicit=explicit)

def _parse_projections(self) -> t.List[exp.Expression]:
    depth = getattr(self, "_redshift_projection_depth", 0)
    self._redshift_projection_depth = depth + 1
