def _parse_select_query(
    self,
    nested: bool = False,
    table: bool = False,
    parse_subquery_alias: bool = True,
    parse_set_operation: bool = True,
) -> t.Optional[exp.Expression]:
    query = super()._parse_select_query(
        nested=nested,
        table=table,
        parse_subquery_alias=parse_subquery_alias,
        parse_set_operation=parse_set_operation,
    )

    if isinstance(query, exp.Select):
        for marker in query.expressions:
            if isinstance(marker, exp.Star) and marker.meta.pop(
                "redshift_projection_exclude", False
            ):
                projections = [e for e in query.expressions if e is not marker]
                inner = query.copy()
                inner.set("expressions", projections)
                outer = exp.Select(
                    expressions=[exp.Star(except_=marker.args.get("except_"))],
                    from_=exp.From(this=inner.subquery(copy=False)),
                )
                outer.meta["redshift_projection_exclude"] = True
                return outer

    return query

